{(\textbf{Adjustment set}; \citealp{maathuis2013generalized})}
   Let $\mathbf{X,Y}$ and $\mathbf{Z}$ be pairwise disjoint node sets in a causal $\mathrm{DAG}$, $\mathrm{CPDAG}$, $\mathrm{MAG}$ or $\mathrm{PAG}$ $\g$. Then $\mathbf{Z}$ is an adjustment set relative to $(\mathbf{X,Y})$ in~$\g$  if for any density\footnote{We use the notation for continuous random variables throughout. The discrete analogues should be obvious.} $f$ consistent with $\g$ we have
   \begin{equation}
   f(\mathbf{y}\mid do(\mathbf{x}))=
   \begin{cases}
   f(\mathbf{y}\mid\mathbf{x}) & \text{if }\mathbf{Z} = \emptyset,\\
   \int_{\mathbf{z}}f(\mathbf{y}\mid\mathbf{x,z})f(\mathbf{z})d\mathbf{z}  & \text{otherwise.}
   \end{cases}
   \label{lab}
   \end{equation}
   \label{defadjustment}

\begin{equation}
   f(\mathbf{y}\mid do(\mathbf{x}))=
   \begin{cases}
   f(\mathbf{y}\mid\mathbf{x}) & \text{if }\mathbf{Z} = \emptyset,\\
   \int_{\mathbf{z}}f(\mathbf{y}\mid\mathbf{x,z})f(\mathbf{z})d\mathbf{z}  & \text{otherwise.}
   \end{cases}
   \label{lab}
   \end{equation}

Suppose $f$ is a multivariate Gaussian density that is consistent with a causal $\mathrm{DAG}$ $\g[D]$. Let $\mathbf{Z} \neq \emptyset$ be an adjustment set relative to two distinct variables $X$ and $Y$ in~$\g[D]$ such that $\mathbf{Z} \cap \{ X \cup Y \} = \emptyset$. Then
\begin{align}
&E(Y \given do(x)) =  \int_{y} y f(y \given do(x))dy  =   \int_{y} y \int_\mathbf{z} f(y \given x,\mathbf{z})f(\mathbf{z})d\mathbf{z}dy  \nonumber \\
& =  \int_\mathbf{z} \int_{y} y f(y \given x,\mathbf{z})dyf(\mathbf{z})d\mathbf{z} = \int_\mathbf{z} E(Y \given x,\mathbf{z})f(\mathbf{z})d\mathbf{z}  \nonumber \\
&=  \int_\mathbf{z}(\alpha + \gamma x + \beta^T \mathbf{z})f(\mathbf{z})d\mathbf{z}=\alpha + \gamma x + \beta^T E(\mathbf{Z}), \nonumber
\end{align}

\noindent{}where we use the fact that all conditional expectations in a multivariate Gaussian distribution are linear, so that $E(Y \given x,\mathbf{z}) = \alpha + \gamma x + \beta^{T} \mathbf{z}$, for some $\alpha, \gamma \in \mathbb{R}$ and $\beta \in \mathbb{R}^{|\mathbf{z}|}$. Defining the total causal effect of $X$ on $Y$ as $\frac{\partial }{\partial x}E(Y \given do(x))$, we obtain that the total causal effect of $X$ on $Y$ is $\gamma$, that is, the regression coefficient of $X$ in the regression of $Y$ on $X$ and $\mathbf{Z}$.
\label{ex:gaussian-linear}

\begin{align}
&E(Y \given do(x)) =  \int_{y} y f(y \given do(x))dy  =   \int_{y} y \int_\mathbf{z} f(y \given x,\mathbf{z})f(\mathbf{z})d\mathbf{z}dy  \nonumber \\
& =  \int_\mathbf{z} \int_{y} y f(y \given x,\mathbf{z})dyf(\mathbf{z})d\mathbf{z} = \int_\mathbf{z} E(Y \given x,\mathbf{z})f(\mathbf{z})d\mathbf{z}  \nonumber \\
&=  \int_\mathbf{z}(\alpha + \gamma x + \beta^T \mathbf{z})f(\mathbf{z})d\mathbf{z}=\alpha + \gamma x + \beta^T E(\mathbf{Z}), \nonumber
\end{align}

{(\textbf{Amenability})}
   Let $\mathbf{X}$ and $\mathbf{Y}$ be disjoint node sets in a $\mathrm{DAG}$, $\mathrm{CPDAG}$, $\mathrm{MAG}$ or $\mathrm{PAG}$ $\g$. Then $\g$ is said to be amenable relative to $(\mathbf{X},\mathbf{Y})$ if every proper possibly directed path from $\mathbf{X}$ to $\mathbf{Y}$ in~$\g$ starts with a visible edge out of $\mathbf{X}$.
  \label{defadjamengen}

(\textbf{Forbidden set; $\fb{\g}$})  Let $\mathbf{X}$ and $\mathbf{Y}$ be disjoint node sets in a $\mathrm{DAG}$, $\mathrm{CPDAG}$, $\mathrm{MAG}$ or $\mathrm{PAG}$ $\g$. Then the forbidden set relative to $(\mathbf{X,Y})$ is defined as
\begin{align}
   \fb{\g} = \{ & W' \in \vars: W' \in \mathrm{PossDe}(W,\g) \text{, for some } W \notin \mathbf{X} \, \notag \\
   & \text{which lies on a proper possibly} \text{ directed path from } \, \mathbf{X} \,\text{to}\, \mathbf{Y}\text{in } \g\}.\notag
\end{align} \label{def:forbidden nodes}

\begin{align}
   \fb{\g} = \{ & W' \in \vars: W' \in \mathrm{PossDe}(W,\g) \text{, for some } W \notin \mathbf{X} \, \notag \\
   & \text{which lies on a proper possibly} \text{ directed path from } \, \mathbf{X} \,\text{to}\, \mathbf{Y}\text{in } \g\}.\notag
\end{align}

(\textbf{Proper back-door graph}; $\gpbd{\mathbf{XY}}$)
  Let $\mathbf{X}$ and $\mathbf{Y}$ be disjoint node sets in a $\mathrm{DAG}$, $\mathrm{CPDAG}$, $\mathrm{MAG}$ or $\mathrm{PAG}$ $\g$. The proper back-door graph $\gpbd{\mathbf{XY}}$ is obtained from $\g$ by removing all visible edges out of $\mathbf{X}$ that are on proper possibly directed paths from $\mathbf{X}$ to $\mathbf{Y}$ in~$\g$.
\label{def:gpbd}

Replacing the Blocking condition in Definition~\ref{def:gac} with:

\begin{enumerate}[label = (\roman*), leftmargin=0.5cm,align=left]
\item[({\bfseries Separation})] \label{cond2prime} $\mathbf{Z}$ m-separates $\mathbf{X}$ and $\mathbf{Y}$ in~$\gpbd{\mathbf{XY}}$,
\end{enumerate}
results in a criterion that is equivalent to the generalized adjustment criterion.
\label{theorem:gac-alt}

