{($\adjustb{\g}$)}
Let $\mathbf{X}$ and $\mathbf{Y}$ be disjoint node sets in a $\mathrm{DAG}$, $\mathrm{CPDAG}$, $\mathrm{MAG}$ or $\mathrm{PAG}$ $\g$. We define
\begin{equation}
\adjustb{\g}=\mathrm{PossAn}(\mathbf{X} \cup \mathbf{Y}, \g)\setminus(\mathbf{X} \cup \mathbf{Y} \cup \fb{\g}).
\end{equation}
\label{def:adjust xy}

\begin{equation}
\adjustb{\g}=\mathrm{PossAn}(\mathbf{X} \cup \mathbf{Y}, \g)\setminus(\mathbf{X} \cup \mathbf{Y} \cup \fb{\g}).
\end{equation}

 \textbf{(Descendral set)}
Let $\mathbf{I}$ be a node set in a $\mathrm{DAG}$, $\mathrm{CPDAG}$, $\mathrm{MAG}$ or $\mathrm{PAG}$ $\g$. Then $\mathbf{I}$ is called descendral in~$\g$ if $\mathbf{I} = \mathrm{PossDe}(\mathbf{I},\g)$.
\label{def:descendral}

(\textbf{Constructive set})
Let $\mathbf{X}$ and $\mathbf{Y}$ be disjoint node sets in a $\mathrm{DAG}$, $\mathrm{CPDAG}$, $\mathrm{MAG}$ or $\mathrm{PAG}$ $\g$. Let $\mathbf{I} \supseteq \fb{\g}$ be a descendral set in~$\g$. Then there exists a set $\mathbf{Z}$ that satisfies the generalized adjustment criterion relative to $(\mathbf{X,Y})$ in~$\g$ such that $\mathbf{Z} \cap \mathbf{I} = \emptyset$ if and only if $\adjustb{\g} \setminus \mathbf{I}$ satisfies the generalized adjustment criterion relative to $(\mathbf{X,Y})$ in~$\g$.
\label{theorem:general set proof}

Consider again the $\mathrm{CPDAG}$ $\g[C]$ in Figure~\ref{fig:cpdagexample}(a). As previously discussed in Example~\ref{ex:everything-works}, $\g[C]$ is amenable relative to $(X,Y)$.
The set $\adjust{\g[C]} = \{ X, Y, I, A, Z, B \} \setminus \{X,Y\} = \{I,A,Z,B \}$ satisfies the blocking condition\xspace{} relative to $(X,Y)$ in~$\g[C]$. Hence, by Corollary~\ref{cor:adjust xy gac general}, $\{I,A,Z,B \}$ satisfies the generalized adjustment criterion relative to $(X,Y)$ in~$\g[C]$.
\label{ex:constr-everything-works}

{(\textbf{Back-door path}; \citealp{maathuis2013generalized})}
Let $X$ and $Y$ be distinct nodes in a $\mathrm{DAG}$, $\mathrm{CPDAG}$, $\mathrm{MAG}$ or $\mathrm{PAG}$ $\g$. A path from $X$ to $Y$ in~$\g$ is a back-door path if it does not start with a visible edge out of $X$.
\label{def:backdoor path}

(\textbf{Constructive back-door set})
Let $\mathbf{X}$ and $\mathbf{Y}$ be disjoint node sets in a $\mathrm{DAG}$ $\g[D]$.
The following statements are equivalent:
\begin{enumerate} [label = (\roman*)]
\item\label{constr-bc-1} There exists a set that satisfies Pearl's back-door criterion relative to $(\mathbf{X,Y})$ in~$\g[D]$.
\item\label{constr-bc-2} $\adjustb{\g[D]}\setminus \mathrm{De}(\mathbf{X},\g[D])$ satisfies Pearl's back-door criterion relative to $(\mathbf{X,Y})$ in~$\g[D]$.
\item\label{constr-bc-3} 
For all $X \in \mathbf{X}$, $Y \in \mathbf{Y}$, $\adjustb{\g[D]} \setminus \mathrm{De}(\mathbf{X},\g[D])$ satisfies condition~\ref{d:bc2} of Pearl's back-door criterion.
\end{enumerate}
\label{cor:constr-bc}

Let $\mathbf{X}$ and $\mathbf{Y}$ be disjoint node sets in a DAG, CPDAG, MAG or PAG $\g$ such that $\g$ is amenable relative to $(\mathbf{X,Y})$. The following statements hold:
\begin{enumerate}[label=(\roman*)]
\item\label{noforbx1}  If $\mathbf{X} \cap \fb{\g} \neq \emptyset$, then there is no adjustment set relative to $(\mathbf{X,Y})$ in $\g$.
\item\label{noforbx2} Let $\g$ be a DAG or CPDAG and $\mathbf{Y} \subseteq \mathrm{PossDe}(\mathbf{X},\g)$. Then $\mathbf{X} \cap \fb{\g} \neq \emptyset$ if and only if there is no adjustment set relative to $(\mathbf{X,Y})$ in $\g$.
\end{enumerate}
\label{cor:noforbx}

Let $\mathbf{X}$ and $\mathbf{Y}$ be disjoint node sets in a $\mathrm{DAG}$ $\g[D]$. If there is no directed path from one node in $\mathbf{X}$ to another node in $\mathbf{X}$ in~$\g[D]$, then the following statements are equivalent:
\begin{enumerate}[label=(\roman*)]
\item\label{l2:1} There exists a set that satisfies the generalized adjustment criterion relative to $(\mathbf{X,Y})$ in~$\g[D]$.
\item\label{l2:2} There exists a back-door set relative to $(\mathbf{X,Y})$ in~$\g[D]$.
\end{enumerate}
\label{cor:equivalence gac bc}

Let $\mathbf{X}$ and $\mathbf{Y}$ be disjoint node sets in a $\mathrm{DAG}$, $\mathrm{CPDAG}$, $\mathrm{MAG}$ or $\mathrm{PAG}$ $\g$. If $\g$ contains no possibly directed path $p = \langle V_1, \dots ,V_k \rangle$ with $k \ge 3$ such that $ \{V_{1},V_{k}\} \subseteq \mathbf{X}$ and $\{V_{2}, \dots ,V_{k-1}\} \cap \mathbf{X} = \emptyset$, or if $\g$ is a $\mathrm{DAG}$ or $\mathrm{CPDAG}$ and $\mathbf{Y} \subseteq \mathrm{PossDe}(\mathbf{X},\g)$, then the following statements are equivalent:
\begin{enumerate}[label=(\roman*)]
\item\label{l:1} There exists a set that satisfies the generalized adjustment criterion relative to $(\mathbf{X,Y})$ in~$\g$.
\item\label{l:2} There exists a generalized back-door set relative to $(\mathbf{X,Y})$ in~$\g$.
\end{enumerate}
\label{cor:equivalence gac gbc}

  Let $\mathbf{X} = \{X_1,X_2\}$ and $\mathbf{Y} = \{ Y \}$ and consider $\mathrm{DAG}$ $\g[D]$ in Figure~\ref{fig:constr-gbc-nodsep}.
The non-causal path $X_1 \leftarrow V_1 \rightarrow X_2 \rightarrow Y$ satisfies~\ref{l:gbc-bc1}$-$\ref{l:gbc-bc4} in Lemma~\ref{lemma:gbc bc}. Hence, no set can satisfy the back-door criterion relative to $(\mathbf{X},\mathbf{Y})$ in~$\g[D]$. However, $\{V_2\}$, $\{V_3\}$, $\{V_2,V_3\}$, $\{V_1,V_2\}$, $\{V_1,V_3\}$, and $\{V_1, V_2, V_3\}$ all satisfy the generalized adjustment criterion and $\{V_2\}$, $\{V_3\}$ and $\{V_2,V_3\}$ all satisfy the generalized back-door criterion relative to $(\mathbf{X},\mathbf{Y})$ in~$\g[D]$.
\label{ex:constr-gbc-nodsep}

 (\textbf{Distance-from-$\mathbf{Z}$})
Let $\mathbf{X,Y}$ and $\mathbf{Z}$ be pairwise disjoint node sets in a $\mathrm{DAG}$, $\mathrm{CPDAG}$, $\mathrm{MAG}$ or $\mathrm{PAG}$ $\g$. Let $p$ be a path between $\mathbf{X}$ and $\mathbf{Y}$ in~$\g$ such that every collider $C$ on $p$ has a possibly directed path (possibly of length $0$) to $\mathbf{Z}$. Define the $distance-from-\!{\mathbf{Z}}$ of $C$ to be the length of a shortest possibly directed path (possibly of length $0$) from $C$ to $\mathbf{Z}$, and define the $distance-from-\!{\mathbf{Z}}$ of $p$ to be the sum of the distances from $\mathbf{Z}$ of the colliders on $p$.
\label{def:distance from Z}

 \citep[cf.\ Theorem 3.2.4][p63]{mardia1980multivariate}
Let $\mathbf{X} = (\mathbf{X_1}^T,\mathbf{X_2}^T)^T$ be a $p$-dimensional multivariate Gaussian random vector with mean vector $\mathbf{\mu} = (\mathbf{\mu_1}^T,\mathbf{\mu_2}^T)^T$ and covariance matrix $\mathbf{\Sigma} = \begin{bmatrix}
\mathbf{\Sigma_{11}} & \mathbf{\Sigma}_{12} \\
\mathbf{\Sigma_{21}} & \mathbf{\Sigma}_{22}
\end{bmatrix}$, so that $\mathbf{X_1}$ is a $q$-dimensional multivariate Gaussian random vector with mean vector $\mathbf{\mu_1}$ and covariance matrix $\mathbf{\Sigma}_{11}$ and  $\mathbf{X_2}$ is a $(p-q)$-dimensional multivariate Gaussian random vector with mean vector $\mathbf{\mu_2}$ and covariance matrix $\mathbf{\Sigma}_{22}$.
Then $E[\mathbf{X_2} \given \mathbf{X_1 = x_1}] = \mathbf{\mu_2} + \mathbf{\Sigma}_{21}\mathbf{\Sigma}_{11}^{-1} (\mathbf{x_1} - \mathbf{\mu_1})$.
\label{theorem:mardia-condexp}

{(\textbf{Moralization}; \citealp{lauritzen1988local})} 
Let $\g[D]$ be a $\mathrm{DAG}$. The \textit{moral} graph $\g[D]^m$ is formed by adding the edge $A-B$ to any structure of the form $A \rightarrow C \leftarrow B$ with $A \notin \mathrm{Adj}(B,\g[D])$ (marrying unmarried parents) and subsequently making all edges in the resulting graph undirected.
\label{def:moralization}

{(\textbf{Induced subgraph})} 
Let $\mathbf{X} \subseteq \mathbf{V}$ be a node set in a $\mathrm{DAG}$ $\g[D] = (\mathbf{V},\mathbf{E})$. Then $\g[D]_\mathbf{X} = (\mathbf{X},\mathbf{E}_\mathbf{X})$, where $\mathbf{E}_\mathbf{X}$ consists of all edges in $\mathbf{E}$ for which both endpoints are in $\mathbf{X}$, is the induced subgraph of $\g[D]$ on $\mathbf{X}$.
\label{def:induced-subgraph}

 (\textbf{Reduction of d-separation to node cuts}; \citealp[cf.\ Proposition 3 in][]{lauritzen1990independence}, \citealp[cf.\ Corollary 2 in][]{richardson2003markov}) 
Let $\g[D]$ be a $\mathrm{DAG}$ and let $\mathbf{X},\mathbf{Y}$ and $\mathbf{Z}$ be pairwise disjoint node sets in~$\g[D]$. Then $\mathbf{Z}$ d-separates $\mathbf{X}$ and $\mathbf{Y}$ in~$\g[D]$ if and only if all paths between $\mathbf{X}$ and $\mathbf{Y}$ in $(\g[D]_{\mathrm{An}(\mathbf{X} \cup \mathbf{Y} \cup \mathbf{Z},\g[D])})^m$ contain at least one node in $\mathbf{Z}$.
\label{theorem:moralization}

