\label{lemma:basic property of cpdags and pags}

 \citep[Lemma~0 in][p208]{zhang2006causal}
Let $X$ and $Y$ be distinct nodes in a $\mathrm{MAG}$ $\g[M]$. If $p = \langle X, \dots ,Z,V,Y \rangle$ is a discriminating path from $X$ to $Y$ for $V$ in a $\mathrm{MAG}$ $\g[M]$, and the corresponding path to $p(X,V)$ in the $\mathrm{PAG}$ $\g[P]$ of $\g[M]$ is (also) a collider path, then the corresponding path to $p$ in $\g[P]$ is also a discriminating path from $X$ to $Y$ for $V$.
 \label{lemma0}

\citep[cf.\ Lemma~1 in][p208]{zhang2006causal}
   Let $X$ and $Y$ be distinct nodes and let $\mathbf{Z}$ be a node set that does not contain $X$ and $Y$ in a $\mathrm{MAG}$ $\g[M]$ ($\mathrm{DAG}$ $\g[D]$). Let $p$ be a shortest path from $X$ to $Y$ that is m-connecting given $\mathbf{Z}$ in $\g[M]$ $(\g[D])$. Let $\g[P]$ be the $\mathrm{PAG}$ of $\g[M]$ ($\mathrm{CPDAG}$ of $\g[D]$) and let $\pstar$ in $\g[P]$ be the corresponding path to $p$ in $\g[M]$ $(\g[D])$. Then $\pstar$ is a definite status path in~$\g[P]$.
  \label{lemma1}

\citep[cf.\ Lemma~2 in][p213]{zhang2006causal}
   Let $X$ and $Y$ be distinct nodes and let $\mathbf{Z}$ be a node set that does not contain $X$ and $Y$ in a $\mathrm{MAG}$ $\g[M]$ ($\mathrm{DAG}$ $\g[D]$). Let $p$ be a shortest path from $X$ to $Y$ that is m-connecting given $\mathbf{Z}$ in $\g[M]$ $(\g[D])$ such that no equally short m-connecting path has a shorter distance-from-$\mathbf{Z}$ (see Definition~\ref{def:distance from Z}) than $p$ does. Let $\g[P]$ be the $\mathrm{PAG}$ of $\g[M]$ ($\mathrm{CPDAG}$ of $\g[D]$) and let $\pstar$ in $\g[P]$ be the corresponding path to $p$ in $\g[M]$ $(\g[D])$. Then $\pstar$ is a definite status path from $X$ to $Y$ that is m-connecting given $\mathbf{Z}$ in $\g[P]$.
  \label{lemma2}

{\citep[cf.\ Lemma~B.1 in][]{zhang2008completeness}}
  Let $X$ and $Y$ be distinct nodes in a $\mathrm{CPDAG}$ or $\mathrm{PAG}$ $\g$. If $p = \langle X, \dots ,Y \rangle$ is a possibly directed path from $X$ to $Y$ in~$\g$, then some subsequence of $p$ forms an unshielded possibly directed path from $X$ to $Y$ in~$\g$.
   \label{lemma:unshielded}

{(\citealp[cf.\ Lemma~B.2 in][]{zhang2008completeness},\citealp[ Lemma 7.2 in][]{maathuis2013generalized})}
Let $X$ and $Y$ be distinct nodes in a $\mathrm{CPDAG}$ or $\mathrm{PAG}$ $\g$. If $p = \langle X=V_0, \dots , V_k=Y \rangle$, $k \geq 2$ is an unshielded possibly directed path from $X$ to $Y$ in~$\g$, and $V_{i-1} \setlength{\unitlength}{1mm} \begin{picture}(5,1)(0,0) \put(0.2,0){$\bullet$} \put(1,0){$\rightarrow$} \end{picture} V_{i}$ for some $i \in \{1,\dots,k\}$, then  $V_{j-1} \rightarrow V_{j}$ for all $j \in \{i+1,\dots,k\}$.
\label{lemma:unshielded edges}

 \citep[Theorem~4.1 in][]{maathuis2013generalized}
Let $X$ and $Y$ be distinct nodes in a $\mathrm{DAG}$, $\mathrm{CPDAG}$, $\mathrm{MAG}$ or $\mathrm{PAG}$ $\g$. Let $\g[R]$ and $\g[R]_{\underline{X}}$ be defined as in Definition
\ref{def:rx}. Then there exists a generalized back-door set relative to $(X,Y)$ in~$\g$ if and only if $Y \notin \mathrm{Adj}(X,\g[R]_{\underline{X}})$ and $
\dsep{\g[R]_{\underline{X}}} \cap \mathrm{PossDe}(X,\g) = \emptyset$. Moreover, if such a set exists, then $\dsep{\g[R]_{\underline{X}}}$ is a generalized back-door set
relative to $(X,Y)$ in~$\g$.
\label{theorem:marloes constructive gbc}

