 {(\textbf{Soundness of the adjustment criterion for $\mathrm{DAG}$s})}
Let $\mathbf{X,Y}$ and $\mathbf{Z_0}$ be pairwise disjoint node sets in a causal $\mathrm{DAG}$ $\g[D]$. If $\mathbf{Z_0}$ satisfies the adjustment criterion (see Definition~\ref{def:johannes ac shpitser}), then $\mathbf{Z_0}$ is an adjustment set (see Definition~\ref{def:pearl adjustment}).
\label{theorem:soundness ac}

Assume that $\mathbf{Z_0}$ satisfies the adjustment criterion (see Definition~\ref{def:johannes ac shpitser}) relative to $(\mathbf{X,Y})$ in~$\g[D]$ and let $f$ be a density consistent with $\g[D]$.
We need to show that

\begin{equation}
f(\mathbf{y} \given \textrm{do}(\mathbf{x})) = \int_{\mathbf{z_0}} f( \mathbf{y} \given \mathbf{x,}\mathbf{z_0}) f(\mathbf{z_0})d\mathbf{z_0}.
\label{eq02}
\end{equation}

Let $\mathbf{Y_D} = \mathbf{Y} \cap \mathrm{De}(\mathbf{X},\g[D])$ and $\mathbf{Y_N} = \mathbf{Y} \setminus \mathrm{De}(\mathbf{X}, \g[D])$.
Then $\mathbf{Y_N} \perp_{d} \mathbf{X}$ in~$\g[D]_{\overline{\mathbf{X}}}$, since $\g[D]_{\overline{\mathbf{X}}}$ does not contain paths into $\mathbf{X}$ and all paths from $\mathbf{X}$ to $\mathbf{Y_N}$ that are out of $\mathbf{X}$ in $\g[D]_{\overline{\mathbf{X}}}$ must contain a collider by definition of $\mathbf{Y_N}$. 
Hence, using Rule 3 of the do-calculus (see Equation \ref{rule3} in Appendix~\ref{subsec:additional}), with $\mathbf{X'} = \emptyset, \mathbf{W'} = \emptyset$, $\mathbf{Z'} = \mathbf{X}$ and $\mathbf{Y'} = \mathbf{Y_N}$ we have
\begin{align}
\begin{split}
&f(\mathbf{y_N}) = f(\mathbf{y_N} \given \textrm{do}(\mathbf{x})). \label{eq0}
\end{split}
\end{align}

Now, assume that $\mathbf{Y_D} = \emptyset$, so that $\mathbf{Y} = \mathbf{Y_N}$. Then all paths from $\mathbf{X}$ to $\mathbf{Y}$ are non-causal in~$\g[D]$.
Since $\mathbf{Z_0}$ satisfies the adjustment criterion relative to ($\mathbf{X,Y}$) in~$\g[D]$ it blocks all proper non-causal paths from $\mathbf{X}$ to $\mathbf{Y}$. Thus, $\mathbf{Z_0}$ also blocks all non-causal paths from $\mathbf{X}$ to $\mathbf{Y}$ in~$\g[D]$, so $\mathbf{X} \perp_{d} \mathbf{Y} \given \mathbf{Z_0}$ in~$\g[D]$.
Combining the probabilistic implications of d-separation and Equation \eqref{eq0} with the right-hand side of Equation \eqref{eq02} we obtain
\begin{align}
\int_{\mathbf{z_0}} f(\mathbf{y} \given \mathbf{x,z_0}) f(\mathbf{z_0})d\mathbf{z_0} &= \int_{\mathbf{z_0}} f(\mathbf{y} \given \mathbf{z_0}) f(\mathbf{z_0})d\mathbf{z_0}  \\ \nonumber
&= f(\mathbf{y}) = f(\mathbf{y} \given \textrm{do}(\mathbf{x})). \nonumber
\end{align}

For the remainder of the proof we assume $\mathbf{Y_D} \neq \emptyset$. We enlarge the set $\mathbf{Z_0}$ to $\mathbf{Z} = \mathbf{Z_0} \cup \mathrm{An}(\mathbf{X} \cup \mathbf{Y},\g[D]) \setminus ( \mathrm{De}(\mathbf{X}, \g[D]) \cup \mathbf{Y})$.
Then applying \ref{l:zp-satisf-ac3}~in~Lemma~\ref{lemma:zprime satisfies ac} to the right-hand side of Equation \eqref{eq02} we get
\begin{align}
\int_{\mathbf{z_0}} f( \mathbf{y} \given \mathbf{x,}\mathbf{z_0}) f(\mathbf{z_0})d\mathbf{z_0} = \int_{\mathbf{z}} f( \mathbf{y} \given \mathbf{x,z}) f(\mathbf{z})d\mathbf{z} .
\label{eq03}
\end{align}

Let $\mathbf{Z_D} = \mathbf{Z} \cap \mathrm{De}(\mathbf{X}, \g[D])$ and $\mathbf{Z_N} = \mathbf{Z} \setminus \mathrm{De}(\mathbf{X}, \g[D])$.
Now suppose that $\mathbf{Y} = \mathbf{Y_D}$, so that $\mathbf{Y_N} = \emptyset$. From~\ref{l:s1} in Lemma~\ref{lemma:shpitser ynyd}, we have $\mathbf{Y_D} \perp_{d} \mathbf{Z_D} \given \mathbf{X} \cup \mathbf{Z_N}$.
Using the probabilistic implications of d-separation, the right-hand side of Equation \eqref{eq03} equals
\begin{align}
\int_{\mathbf{z_D,z_N}} f( \mathbf{y} \given \mathbf{x,z_D,z_N})  f(\mathbf{z_D,z_N})d\mathbf{z_D}d\mathbf{z_N} &= \int_{\mathbf{z_D,z_N}} f( \mathbf{y} \given \mathbf{x,z_N})  f(\mathbf{z_D,z_N})d\mathbf{z_D}d\mathbf{z_N} \nonumber \\
&= \int_{\mathbf{z_N}} f( \mathbf{y} \given \mathbf{x,z_N}) f(\mathbf{z_N})d\mathbf{z_N}. \label{eq3}
\end{align}

Since $\mathbf{Z_N}$ satisfies the generalized back-door criterion relative to $(\mathbf{X,Y})$ in~$\g[D]$ (see~\ref{l:s2} in Lemma~\ref{lemma:shpitser ynyd}) and since the generalized back-door criterion is sound by Theorem 3.1 in \cite{maathuis2013generalized}, we have
\begin{align}
\int_{\mathbf{z_N}} f( \mathbf{y} \given \mathbf{x,z_N}) f(\mathbf{z_N}) d\mathbf{z_N}
& = f(\mathbf{y} \given \textrm{do}(\mathbf{x})). \label{eq33}
\end{align}

\noindent{}Combining Equations \eqref{eq03}, \eqref{eq3} and \eqref{eq33} completes the proof when $\mathbf{Y_N} = \emptyset$.
In the remainder of the proof we assume $\mathbf{Y_D} \neq \emptyset$ and $\mathbf{Y_N} \neq \emptyset$.
From~\ref{l:s1} in Lemma~\ref{lemma:shpitser ynyd}, $\mathbf{Y_D} \perp_{d} \mathbf{Z_D} \given \mathbf{Y_N} \cup \mathbf{X} \cup \mathbf{Z_N}$. Using the probabilistic implications of d-separation, the right-hand side of Equation \eqref{eq03} equals
\begin{align}
& \int_{\mathbf{z_D,z_N}} f( \mathbf{y_D,y_N} \given \mathbf{x,z_D,z_N})  f(\mathbf{z_D,z_N}) d\mathbf{z_D}d\mathbf{z_N} \nonumber \\
& =\int_{\mathbf{z_D,z_N}} f( \mathbf{y_D} \given \mathbf{y_N,x,z_D,z_N}) f(\mathbf{y_N} \given \mathbf{x,z_D,z_N}) f(\mathbf{z_D,z_N}) d\mathbf{z_D}d\mathbf{z_N} \nonumber \\
&= \int_{\mathbf{z_N}} f( \mathbf{y_D} \given \mathbf{y_N,x,z_N}) \int_{\mathbf{z_D}} f(\mathbf{y_N} \given \mathbf{x,z_D,z_N}) f(\mathbf{z_D,z_N}) d\mathbf{z_D}d\mathbf{z_N}. \label{eq333}
\end{align}

Since $\mathbf{Z}$ satisfies the adjustment criterion relative to $(\mathbf{X,Y})$ in~$\g[D]$ (\ref{l:zp-satisf-ac2}~in~Lemma~\ref{lemma:zprime satisfies ac}), $\mathbf{Z}$ blocks all proper non-causal paths from $\mathbf{X}$ to $\mathbf{Y}$. Hence, $\mathbf{Z}$ blocks all proper paths from $\mathbf{X}$ to $\mathbf{Y_N}$ in~$\g[D]$, so $\mathbf{X} \perp_{d} \mathbf{Y_N} \given \mathbf{Z}$ in~$\g[D]$. Additionally, the empty set satisfies the generalized back-door criterion relative to ($(\mathbf{Y_N} \cup \mathbf{X} \cup \mathbf{Z_N}),\mathbf{Y_D}$) (\ref{l:s3} in Lemma~\ref{lemma:shpitser ynyd}). 
Since the generalized back-door criterion is sound by Theorem 3.1 in \cite{maathuis2013generalized}, we apply this to the right-hand side of Equation \eqref{eq333}
\begin{align}
  & \int_{\mathbf{z_N}} f( \mathbf{y_D} \given \mathbf{y_N,x,z_N}) \int_{\mathbf{z_D}} f(\mathbf{y_N} \given \mathbf{x,z_D,z_N}) f(\mathbf{z_D,z_N})d\mathbf{z_D}d\mathbf{z_N}  \nonumber  \\
  &= \int_{\mathbf{z_N}} f( \mathbf{y_D} \given \textrm{do}(\mathbf{x,y_N,z_N})) \int_{\mathbf{z_D}}  f(\mathbf{y_N} \given \mathbf{z_N,z_D}) f(\mathbf{z_D,z_N})d\mathbf{z_D}d\mathbf{z_N} \nonumber \\
  &= \int_{\mathbf{z_N}}  f( \mathbf{y_D} \given \textrm{do}(\mathbf{x,y_N,z_N})) f(\mathbf{z_N} \given \mathbf{y_N}) f(\mathbf{y_N})d\mathbf{z_N}. \label{eq4}
\end{align}

To finish the proof we rely on the $\textrm{do}$-calculus rules. By~\ref{l:s4}~in~Lemma~\ref{lemma:shpitser ynyd}, it follows that
$\mathbf{Y_N} \cup\mathbf{Z_N} \perp_{d} \mathbf{Y_D} \given \mathbf{X}$ in~$\g[D]_{\overline{\mathbf{X}}\underline{\mathbf{Y_N} \cup  \mathbf{Z_N}}}$.
Using Rule 2 of the $\textrm{do}$-calculus (see Equation \ref{rule2} in Appendix~\ref{subsec:additional}) with $\mathbf{X'} = \mathbf{X}, \mathbf{W'} = \emptyset$, $\mathbf{Z'} = \mathbf{Y_N} \cup \mathbf{Z_N}$ and $\mathbf{Y'} = \mathbf{Y_D}$:
\begin{align}
f( \mathbf{y_D} \given \textrm{do}(\mathbf{x,y_N,z_N})) = f( \mathbf{y_D} \given \textrm{do}(\mathbf{x}),\mathbf{z_N,y_N}).
\label{eqdorules1}
\end{align}

\noindent{}Additionally, by~\ref{l:s5}~in~Lemma~\ref{lemma:shpitser ynyd}, $\mathbf{Z_N} \perp_{d} \mathbf{X} \given \mathbf{Y_N}$ in~$\g[D]_{\overline{\mathbf{X}}}$. Using Rule 3 of the $\textrm{do}$-calculus (see Equation \ref{rule3} in Appendix~\ref{subsec:additional}) with $\mathbf{X'} = \emptyset, \mathbf{W'} = \mathbf{Y_N}$, $\mathbf{Z'} = \mathbf{X}$ and $\mathbf{Y'} = \mathbf{Z_N}$:
\begin{align}
f(\mathbf{z_N} \given \mathbf{y_N}) =  f(\mathbf{z_N} \given  \textrm{do}(\mathbf{x}),\mathbf{y_N}).
\label{eqdorules2}
\end{align}

\noindent{}Finally, we combine Equations \eqref{eqdorules1},\eqref{eqdorules2} and \eqref{eq0} with the right-hand side of Equation \eqref{eq4}:
\begin{align}
& \int_{\mathbf{z_N}}  f( \mathbf{y_D} \given \textrm{do}(\mathbf{y_N,x,z_N})) f(\mathbf{z_N} \given \mathbf{y_N}) f(\mathbf{y_N}) d\mathbf{z_N} \nonumber  \\
&= \int_{\mathbf{z_N}} f( \mathbf{y_D} \given \mathbf{z_N,y_N}, \textrm{do}(\mathbf{x}))  f(\mathbf{z_N} \given \mathbf{y_N}, \textrm{do}(\mathbf{x})) f(\mathbf{y_N} \given \textrm{do}(\mathbf{x})) d\mathbf{z_N} \nonumber \\
&= \int_{\mathbf{z_N}} f( \mathbf{y_D,z_N} \given \mathbf{y_N}, \textrm{do}(\mathbf{x}))   f(\mathbf{y_N} \given \textrm{do}(\mathbf{x})) d\mathbf{z_N} \nonumber \\
&= f( \mathbf{y_D} \given \mathbf{y_N}, \textrm{do}(\mathbf{x}))   f(\mathbf{y_N} \given \textrm{do}(\mathbf{x})) =f(\mathbf{y_D,y_N} \given \textrm{do}(\mathbf{x})) = f(\mathbf{y} \given \textrm{do}(\mathbf{x})).  \nonumber
\end{align}

\begin{equation}
f(\mathbf{y} \given \textrm{do}(\mathbf{x})) = \int_{\mathbf{z_0}} f( \mathbf{y} \given \mathbf{x,}\mathbf{z_0}) f(\mathbf{z_0})d\mathbf{z_0}.
\label{eq02}
\end{equation}

\begin{align}
\begin{split}
&f(\mathbf{y_N}) = f(\mathbf{y_N} \given \textrm{do}(\mathbf{x})). \label{eq0}
\end{split}
\end{align}

\begin{align}
\int_{\mathbf{z_0}} f(\mathbf{y} \given \mathbf{x,z_0}) f(\mathbf{z_0})d\mathbf{z_0} &= \int_{\mathbf{z_0}} f(\mathbf{y} \given \mathbf{z_0}) f(\mathbf{z_0})d\mathbf{z_0}  \\ \nonumber
&= f(\mathbf{y}) = f(\mathbf{y} \given \textrm{do}(\mathbf{x})). \nonumber
\end{align}

\begin{align}
\int_{\mathbf{z_0}} f( \mathbf{y} \given \mathbf{x,}\mathbf{z_0}) f(\mathbf{z_0})d\mathbf{z_0} = \int_{\mathbf{z}} f( \mathbf{y} \given \mathbf{x,z}) f(\mathbf{z})d\mathbf{z} .
\label{eq03}
\end{align}

\begin{align}
\int_{\mathbf{z_D,z_N}} f( \mathbf{y} \given \mathbf{x,z_D,z_N})  f(\mathbf{z_D,z_N})d\mathbf{z_D}d\mathbf{z_N} &= \int_{\mathbf{z_D,z_N}} f( \mathbf{y} \given \mathbf{x,z_N})  f(\mathbf{z_D,z_N})d\mathbf{z_D}d\mathbf{z_N} \nonumber \\
&= \int_{\mathbf{z_N}} f( \mathbf{y} \given \mathbf{x,z_N}) f(\mathbf{z_N})d\mathbf{z_N}. \label{eq3}
\end{align}

\begin{align}
\int_{\mathbf{z_N}} f( \mathbf{y} \given \mathbf{x,z_N}) f(\mathbf{z_N}) d\mathbf{z_N}
& = f(\mathbf{y} \given \textrm{do}(\mathbf{x})). \label{eq33}
\end{align}

\begin{align}
& \int_{\mathbf{z_D,z_N}} f( \mathbf{y_D,y_N} \given \mathbf{x,z_D,z_N})  f(\mathbf{z_D,z_N}) d\mathbf{z_D}d\mathbf{z_N} \nonumber \\
& =\int_{\mathbf{z_D,z_N}} f( \mathbf{y_D} \given \mathbf{y_N,x,z_D,z_N}) f(\mathbf{y_N} \given \mathbf{x,z_D,z_N}) f(\mathbf{z_D,z_N}) d\mathbf{z_D}d\mathbf{z_N} \nonumber \\
&= \int_{\mathbf{z_N}} f( \mathbf{y_D} \given \mathbf{y_N,x,z_N}) \int_{\mathbf{z_D}} f(\mathbf{y_N} \given \mathbf{x,z_D,z_N}) f(\mathbf{z_D,z_N}) d\mathbf{z_D}d\mathbf{z_N}. \label{eq333}
\end{align}

\begin{align}
  & \int_{\mathbf{z_N}} f( \mathbf{y_D} \given \mathbf{y_N,x,z_N}) \int_{\mathbf{z_D}} f(\mathbf{y_N} \given \mathbf{x,z_D,z_N}) f(\mathbf{z_D,z_N})d\mathbf{z_D}d\mathbf{z_N}  \nonumber  \\
  &= \int_{\mathbf{z_N}} f( \mathbf{y_D} \given \textrm{do}(\mathbf{x,y_N,z_N})) \int_{\mathbf{z_D}}  f(\mathbf{y_N} \given \mathbf{z_N,z_D}) f(\mathbf{z_D,z_N})d\mathbf{z_D}d\mathbf{z_N} \nonumber \\
  &= \int_{\mathbf{z_N}}  f( \mathbf{y_D} \given \textrm{do}(\mathbf{x,y_N,z_N})) f(\mathbf{z_N} \given \mathbf{y_N}) f(\mathbf{y_N})d\mathbf{z_N}. \label{eq4}
\end{align}

\begin{align}
f( \mathbf{y_D} \given \textrm{do}(\mathbf{x,y_N,z_N})) = f( \mathbf{y_D} \given \textrm{do}(\mathbf{x}),\mathbf{z_N,y_N}).
\label{eqdorules1}
\end{align}

\begin{align}
f(\mathbf{z_N} \given \mathbf{y_N}) =  f(\mathbf{z_N} \given  \textrm{do}(\mathbf{x}),\mathbf{y_N}).
\label{eqdorules2}
\end{align}

\begin{align}
& \int_{\mathbf{z_N}}  f( \mathbf{y_D} \given \textrm{do}(\mathbf{y_N,x,z_N})) f(\mathbf{z_N} \given \mathbf{y_N}) f(\mathbf{y_N}) d\mathbf{z_N} \nonumber  \\
&= \int_{\mathbf{z_N}} f( \mathbf{y_D} \given \mathbf{z_N,y_N}, \textrm{do}(\mathbf{x}))  f(\mathbf{z_N} \given \mathbf{y_N}, \textrm{do}(\mathbf{x})) f(\mathbf{y_N} \given \textrm{do}(\mathbf{x})) d\mathbf{z_N} \nonumber \\
&= \int_{\mathbf{z_N}} f( \mathbf{y_D,z_N} \given \mathbf{y_N}, \textrm{do}(\mathbf{x}))   f(\mathbf{y_N} \given \textrm{do}(\mathbf{x})) d\mathbf{z_N} \nonumber \\
&= f( \mathbf{y_D} \given \mathbf{y_N}, \textrm{do}(\mathbf{x}))   f(\mathbf{y_N} \given \textrm{do}(\mathbf{x})) =f(\mathbf{y_D,y_N} \given \textrm{do}(\mathbf{x})) = f(\mathbf{y} \given \textrm{do}(\mathbf{x})).  \nonumber
\end{align}

Let $\mathbf{X},\mathbf{Y}$ and $\mathbf{Z_0}$ be pairwise disjoint node sets in a $\mathrm{DAG}$ $\g[D]$ such that $\mathbf{Z_0}$ satisfies the adjustment criterion relative to $(\mathbf{X,Y})$ in $\g[D]$. Let $\mathbf{Z_1} \subseteq \mathrm{An}(\mathbf{X} \cup \mathbf{Y},\g[D]) \setminus ( \mathrm{De}(\mathbf{X}, \g[D]) \cup \mathbf{Y})$ and $\mathbf{Z} = \mathbf{Z_0} \cup \mathbf{Z_1}$.
Then:
\begin{enumerate}[label = (\roman*)]
\item\label{l:zp-satisf-ac1} $\mathbf{X,Y}$ and $\mathbf{Z}$ are pairwise disjoint, and
\item\label{l:zp-satisf-ac2} $\mathbf{Z}$ satisfies the adjustment criterion relative to $(\mathbf{X,Y})$ in~$\g[D]$, and
\item\label{l:zp-satisf-ac3} $\int_\mathbf{z_0} f(\mathbf{y} \mid \mathbf{x,z_0})f(\mathbf{z_0}) d\mathbf{z_0}
= \int_{\mathbf{z_0,z_1}} f(\mathbf{y} \mid \mathbf{x,z_0,z_1}) f(\mathbf{z_0,z_1}) d\mathbf{z_0}d\mathbf{z_1},$ for any density $f$ consistent with $\g[D]$.
\end{enumerate}
\label{lemma:zprime satisfies ac}

\begin{align}
\int_\mathbf{z_0} f(\mathbf{y} \mid \mathbf{x,z_0})f(\mathbf{z_0}) d\mathbf{z_0}
&= \int_{\mathbf{z_0}} f(\mathbf{y} \mid \mathbf{x,z_0}) \int_{z_1} f(\mathbf{z_0},z_1) dz_1d\mathbf{z_0}  \nonumber \\
&= \int_{\mathbf{z_0},z_1} f(\mathbf{y} \mid \mathbf{x,z_0},z_1) f(\mathbf{z_0},z_1) d\mathbf{z_0}dz_1 \nonumber \\
&= \int_{\mathbf{z'_0}} f(\mathbf{y} \mid \mathbf{x,z'_0}) f(\mathbf{z'_0}) d\mathbf{z'_0}. \label{l1:a}
\end{align}

\begin{align}
\int_\mathbf{z'_0} f(\mathbf{y} \mid \mathbf{x,z'_0})f(\mathbf{z'_0}) d\mathbf{z'_0}
= \int_{\mathbf{z'_0,z'_1}} f(\mathbf{y} \mid \mathbf{x,z'_0,z'_1}) f(\mathbf{z'_0,z'_1}) d\mathbf{z'_0}d\mathbf{z'_1}. \label{l1:b}
\end{align}

\begin{align}
\int_\mathbf{z_0} f(\mathbf{y} \mid \mathbf{x,z_0})f(\mathbf{z_0}) d\mathbf{z_0}
= \int_{\mathbf{z_0,z_1}} f(\mathbf{y} \mid \mathbf{x,z_0,z_1}) f(\mathbf{z_0,z_1}) d\mathbf{z_0}d\mathbf{z_1}. \nonumber
\end{align}

\begin{align}
\int_\mathbf{z_0} f(\mathbf{y} \mid \mathbf{x,z_0})f(\mathbf{z_0})d\mathbf{z_0} &= \int_\mathbf{z_0} f(\mathbf{y} \mid \mathbf{x,z_0})\int_{z_1}f(\mathbf{z_0},z_1)dz_1d\mathbf{z_0} \nonumber \\
&= \int_{\mathbf{z_0},z_1} f(\mathbf{y} \mid \mathbf{x,z_0}) f(\mathbf{z_0},z_1)d\mathbf{z_0}dz_1 \nonumber \\
&= \int_{\mathbf{z_0},z_1} f(\mathbf{y} \mid \mathbf{x,z_0},z_1)f(\mathbf{z_0},z_1)d\mathbf{z_0}dz_1. \nonumber 
\end{align}
